// qsm-web's function-hooks module.
import type { On } from "claude-code";
import { registerNoun } from "./noun.generated.ts";

export function register(on: On): void {
  // Adds $.web: one method per qsm-web verb that has a JSON form, generated by
  // lib/generate-noun.ts. Never hand-edit noun.generated.ts or types/index.d.ts; run the generator
  // after changing qsm.json.
  registerNoun(on);
}
